export const meta = {
  name: 'triage-classify',
  description: 'Classify untriaged upstream mirror stubs into tri:* dispositions',
  phases: [{ title: 'Classify', detail: 'read-only scouts, ~20 stubs each, gh signals only' }],
}
const PATH = args.path
const TOTAL = args.total
const BATCH = args.batch
const RUBRIC = `You are a read-only triage classifier for the beads project (upstream repo gastownhall/beads).
Context: "we" are maphew plus an agent fleet co-maintaining beads from a coordination repo; we review contributor PRs, fix bugs via fork PRs, and have real capacity, so "claim" is common for well-specified work. Storage-layer/dolt-internal items are still claimable (as validation/upstream-report work).

For EACH item in your slice, fetch upstream signals with gh (READ-ONLY — you must not post, comment, label, or write anything anywhere; no bd commands at all):
- issues (ref gh-iss-N):  gh issue view N --repo gastownhall/beads --json state,stateReason,labels,createdAt,updatedAt,author,title,body,comments --jq '{state,stateReason,labels:[.labels[].name],createdAt,updatedAt,author:.author.login,title,body:(.body//""|.[0:1200]),ncomments:(.comments|length),lastComment:((.comments[-1].body // "")|.[0:400])}'
- PRs (ref gh-pr-N):      gh pr view N --repo gastownhall/beads --json state,isDraft,mergeable,reviewDecision,labels,createdAt,updatedAt,author,title,body,comments --jq '{state,isDraft,mergeable,reviewDecision,labels:[.labels[].name],createdAt,updatedAt,author:.author.login,title,body:(.body//""|.[0:1200]),ncomments:(.comments|length)}'
Batch several fetches per Bash call (cmd1; cmd2; ...) to be efficient. If a fetch fails, retry once, then classify needs-info/low.

Dispositions:
- close: obsolete, duplicate of another tracked item, already handled/fixed upstream, upstream item is CLOSED/MERGED, or clearly not actionable by us.
- defer: real but not now (nice-to-have, blocked on upstream direction, stale contributor PR without urgency).
- claim: we should do it and the spec is clear enough to act on (bug with repro, well-scoped feature, reviewable contributor PR).
- human: owner judgment required — contentious/social/high-stakes: release policy, versioning/compat promises, security disclosure, licensing, pricing/hosting, direction disputes.
- needs-info: cannot classify from available signals.
Priority: 0 critical (data loss/corruption/broken builds/security), 1 high, 2 medium default, 3 low/polish, 4 backlog.
confidence: high only when the signals are unambiguous (e.g. upstream terminal, exact duplicate, crisp repro); else medium/low.
reason: ONE sentence, max 200 chars, concrete (name the deciding signal).

Return via StructuredOutput: results = one entry per item in your slice, id and ref copied verbatim from the slice.`

const SCHEMA = {
  type: 'object',
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          ref: { type: 'string' },
          disposition: { enum: ['close', 'defer', 'claim', 'human', 'needs-info'] },
          priority: { type: 'integer', minimum: 0, maximum: 4 },
          reason: { type: 'string', maxLength: 200 },
          confidence: { enum: ['high', 'medium', 'low'] },
        },
        required: ['id', 'ref', 'disposition', 'priority', 'reason', 'confidence'],
      },
    },
  },
  required: ['results'],
}

phase('Classify')
const nBatches = Math.ceil(TOTAL / BATCH)
const TARGET = budget.total ?? 200_000
const thunks = []
for (let i = 0; i < nBatches; i++) {
  const lo = i * BATCH
  const hi = Math.min(TOTAL, lo + BATCH)
  thunks.push(() => {
    if (budget.spent() > TARGET) { log(`budget target ${TARGET} reached — skipping batch ${i}`); return Promise.resolve(null) }
    return agent(
      `${RUBRIC}\n\nYour slice: run this to get your items (a JSON array of {id, ref, type, p, title}):\n  jq -c '.[${lo}:${hi}]' ${PATH}\nClassify exactly these ${hi - lo} items (slice indexes ${lo}..${hi - 1}).`,
      { label: `classify:${lo}-${hi - 1}`, phase: 'Classify', schema: SCHEMA, model: 'sonnet', effort: 'low' }
    )
  })
}
const out = await parallel(thunks)
const missing = out.filter(r => !r).length
if (missing) log(`${missing} batch(es) returned null — their items stay unclassified for a re-run`)
const results = out.filter(Boolean).flatMap(r => r.results)
log(`classified ${results.length} of ${TOTAL}`)
return { results, classified: results.length, total: TOTAL }

